document.addEventListener("DOMContentLoaded",()=>{function e(e){return/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e)}let t=document.querySelector('form[name="contact"]'),i=document.querySelector(".contact-form-submit-button");t.addEventListener("submit",async s=>{s.preventDefault();let r=new FormData(t);if(!e(r.get("email"))){Swal.fire({icon:"warning",text:"Please enter a valid email."});return}if(""==r.get("message").trim()){Swal.fire({icon:"warning",text:"Please enter a message."});return}i.querySelector("p").innerHTML="Sending<br><span>Please wait</span>",i.disabled=!0;let n=document.querySelector("#submit-spinner");n&&n.classList.add("show");try{let a=await fetch("https://contact-backend.fly.dev/submit",{method:"POST",body:r});if(console.log(a),a.ok)await a.json(),Swal.fire({icon:"success",title:"Submission Successful",text:"We will get back to you soon."}),t.reset(),n&&n.classList.remove("show");else{let o=await a.json();429==a.status?Swal.fire({icon:"error",title:"Submission Failed",text:"Too many requests. Please try again later."}):Swal.fire({icon:"error",title:"Submission Failed",text:o.detail||o.error||"Submission failed"})}}catch(l){Swal.fire({icon:"error",text:"Submission failed"})}finally{i.querySelector("p").innerHTML="SUBMIT",i.disabled=!1,n&&n.classList.remove("show")}})});